=<!DOCTYPE html>
<html>
<head>
  <title>🤖 Agent 2 - Domande di Validazione</title>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      min-height: 100vh;
      padding: 20px;
      display: flex;
      justify-content: center;
      align-items: flex-start;
      padding-top: 40px;
    }
    .container {
      background: white;
      max-width: 900px;
      width: 100%;
      border-radius: 20px;
      box-shadow: 0 30px 90px rgba(0,0,0,0.4);
      overflow: hidden;
      animation: slideIn 0.5s;
    }
    @keyframes slideIn {
      from { opacity: 0; transform: translateY(-30px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .header {
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      color: white;
      padding: 40px;
      text-align: center;
      position: relative;
    }
    .header h1 { font-size: 32px; margin-bottom: 10px; font-weight: 700; }
    .header p { opacity: 0.95; font-size: 15px; }
    .content { padding: 45px; }
    .iteration-badge {
      display: inline-block;
      background: linear-gradient(135deg, #fbbf24 0%, #f59e0b 100%);
      color: #78350f;
      padding: 8px 20px;
      border-radius: 25px;
      font-size: 13px;
      font-weight: 700;
      margin-bottom: 25px;
      box-shadow: 0 4px 12px rgba(251, 191, 36, 0.3);
    }
    .summary {
      background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
      border-left: 5px solid #f59e0b;
      padding: 20px;
      margin-bottom: 35px;
      border-radius: 8px;
      box-shadow: 0 2px 8px rgba(0,0,0,0.05);
    }
    .summary h3 {
      color: #78350f;
      margin-bottom: 15px;
      font-size: 18px;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .summary-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 12px;
      margin-top: 12px;
    }
    .summary-item {
      background: white;
      padding: 10px 15px;
      border-radius: 6px;
      font-size: 14px;
    }
    .summary-item strong { color: #92400e; }
    .question-block {
      background: linear-gradient(135deg, #f9fafb 0%, #f3f4f6 100%);
      border: 2px solid #e5e7eb;
      border-radius: 12px;
      padding: 30px;
      margin-bottom: 30px;
      transition: all 0.3s;
      position: relative;
    }
    .question-block:hover {
      border-color: #667eea;
      box-shadow: 0 8px 24px rgba(102, 126, 234, 0.15);
      transform: translateY(-2px);
    }
    .question-number {
      position: absolute;
      top: -15px;
      left: 20px;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      color: white;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 16px;
      box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
    }
    .question-label {
      font-weight: 600;
      color: #1f2937;
      margin-bottom: 18px;
      margin-top: 10px;
      font-size: 17px;
      line-height: 1.5;
    }
    .severity-badge {
      display: inline-block;
      padding: 4px 12px;
      border-radius: 15px;
      font-size: 11px;
      margin-left: 10px;
      font-weight: 700;
      vertical-align: middle;
    }
    .severity-CRITICAL { background: #fee2e2; color: #991b1b; }
    .severity-HIGH { background: #fed7aa; color: #9a3412; }
    .severity-MEDIUM { background: #fef3c7; color: #78350f; }
    .severity-LOW { background: #dbeafe; color: #1e40af; }
    textarea {
      width: 100%;
      padding: 16px;
      border: 2px solid #d1d5db;
      border-radius: 10px;
      font-size: 15px;
      font-family: inherit;
      resize: vertical;
      min-height: 120px;
      transition: all 0.3s;
      line-height: 1.6;
    }
    textarea:focus {
      outline: none;
      border-color: #667eea;
      box-shadow: 0 0 0 4px rgba(102, 126, 234, 0.1);
    }
    .suggested-answers {
      margin-top: 15px;
      padding: 15px;
      background: white;
      border-radius: 8px;
      font-size: 13px;
      color: #6b7280;
      border: 1px solid #e5e7eb;
    }
    .suggested-answers strong { color: #374151; display: block; margin-bottom: 8px; }
    .suggested-answers ul { padding-left: 25px; }
    .suggested-answers li { margin-bottom: 5px; line-height: 1.5; }
    button {
      width: 100%;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      color: white;
      border: none;
      padding: 20px;
      border-radius: 12px;
      font-size: 17px;
      font-weight: 700;
      cursor: pointer;
      transition: all 0.3s;
      margin-top: 30px;
      box-shadow: 0 8px 20px rgba(102, 126, 234, 0.3);
    }
    button:hover {
      transform: translateY(-3px);
      box-shadow: 0 12px 30px rgba(102, 126, 234, 0.4);
    }
    button:active { transform: translateY(-1px); }
    .footer {
      text-align: center;
      padding: 25px;
      color: #9ca3af;
      font-size: 13px;
      border-top: 1px solid #e5e7eb;
      background: #f9fafb;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🤖 Agent 2 - Validazione DDD</h1>
      <p>Rispond alle domande per raffinare collaborativamente il modello</p>
    </div>
    <div class="content">
      <div class="iteration-badge">
        ⚡ Iterazione {{ $json.iteration + 1 }} di {{ $json.max_iterations }}
      </div>

      <div class="summary">
        <h3>📊 Riepilogo Problemi Rilevati</h3>
        <div class="summary-grid">
          <div class="summary-item">
            <strong>{{ JSON.parse($json.summary).total_issues || 0 }}</strong> Problemi totali
          </div>
          <div class="summary-item">
            <strong>{{ JSON.parse($json.summary).entity_overlaps || 0 }}</strong> Entity overlaps
          </div>
          <div class="summary-item">
            <strong>{{ JSON.parse($json.summary).requirement_conflicts || 0 }}</strong> Conflitti requisiti
          </div>
          <div class="summary-item">
            <strong>{{ JSON.parse($json.summary).event_architecture_violations || 0 }}</strong> Violazioni eventi
          </div>
        </div>
      </div>

      <form id="answersForm">
        <input type="hidden" name="session_id" value="{{ $json.session_id }}">
        <input type="hidden" name="iteration" value="{{ $json.iteration + 1 }}">
        <input type="hidden" name="domain_model" value='{{ $json.refined_model || $json.domain_model }}'>
        <input type="hidden" name="max_iterations" value="{{ $json.max_iterations }}">

        {{ JSON.parse($json.follow_up_questions).map((q, i) => `
          <div class="question-block">
            <div class="question-number">${i + 1}</div>
            <div class="question-label">
              ${q.question}
              <span class="severity-badge severity-${q.severity || 'MEDIUM'}">${q.severity || 'MEDIUM'}</span>
            </div>
            <textarea 
              name="q${i}" 
              id="answer_${i}" 
              placeholder="Inserisci la tua risposta dettagliata..."
              required
            ></textarea>
            ${q.suggested_answers && q.suggested_answers.length > 0 ? `
              <div class="suggested-answers">
                <strong>💡 Suggerimenti di risposta:</strong>
                <ul>
                  ${q.suggested_answers.map(s => `<li>${s}</li>`).join('')}
                </ul>
              </div>
            ` : ''}
          </div>
        `).join('') }}

        <button type="submit">✅ Invia Risposte e Continua Raffinamento</button>
      </form>
    </div>
    <div class="footer">
      🤖 Agent 2 - Consistency & Conflict Analyzer | Powered by n8n + Ollama + Llama3
    </div>
  </div>

  <script>
    document.getElementById('answersForm').addEventListener('submit', async function(e) {
      e.preventDefault();
      const formData = new FormData(this);
      const data = {
        session_id: formData.get('session_id'),
        iteration: parseInt(formData.get('iteration')),
        max_iterations: parseInt(formData.get('max_iterations')),
        domain_model: JSON.parse(formData.get('domain_model')),
        answers: {}
      };

      // Raccogli risposte
      for (let [key, value] of formData.entries()) {
        if (key.startsWith('q')) {
          data.answers[key] = value;
        }
      }

      // Mostra loading
      const btn = document.querySelector('button');
      btn.innerHTML = '⏳ Elaborazione risposte e rianalisi in corso...';
      btn.disabled = true;
      document.querySelectorAll('textarea').forEach(t => t.disabled = true);

      try {
        // Richiama lo stesso webhook con le risposte
        const response = await fetch('http://127.0.0.1:5678/webhook/agent2-start', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data)
        });

        if (response.ok) {
          // Sostituisci la pagina con la risposta
          document.body.innerHTML = await response.text();
        } else {
          throw new Error('Errore nella richiesta');
        }
      } catch (error) {
        alert('Errore nell\'invio. Riprova.');
        btn.innerHTML = '✅ Invia Risposte e Continua Raffinamento';
        btn.disabled = false;
        document.querySelectorAll('textarea').forEach(t => t.disabled = false);
      }
    });
  </script>
</body>
</html>
